package cn.mop.api;
import cn.mop.domain.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import org.junit.jupiter.api.*;
import org.springframework.mock.web.MockHttpServletRequest;
import java.nio.charset.StandardCharsets;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
class CustomerContactImportPreviewControllerTest {
    static final String ACTOR="65000000-0000-4000-8000-000000000001",TENANT="65000000-0000-4000-8000-000000000002";
    PlatformRepository platform;CustomerContactImportPreviewController controller;ObjectMapper mapper=new ObjectMapper();
    @BeforeEach void setup(){platform=mock(PlatformRepository.class);controller=new CustomerContactImportPreviewController(platform);member("padmin",true,1);}
    void member(String role,boolean active,long version){when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.of(new Membership(ACTOR,TENANT,role,version,active)));}
    MockHttpServletRequest request(String body){var r=new MockHttpServletRequest("POST","/api/v1/contacts/import-preview");r.setUserPrincipal(()->ACTOR);r.getSession().setAttribute("mop.tenant_id",TENANT);r.setContent(body.getBytes(StandardCharsets.UTF_8));r.setContentType("application/json");return r;}
    ObjectNode row(){var r=mapper.createObjectNode();r.put("name","synthetic");r.putArray("roles").add("REPORTER");r.putNull("mobile");r.putNull("email");r.putNull("wecom_user_id");r.putNull("preferred_priorities");r.putNull("quiet_window");r.put("enabled",true);return r;}
    String input(JsonNode... rows){var body=mapper.createObjectNode();var a=body.putArray("rows");for(var r:rows)a.add(r);return body.toString();}
    Map<?,?> data(String body){return (Map<?,?>)((Map<?,?>)controller.preview(request(body))).get("data");}
    List<Map<?,?>> rows(Map<?,?> value){return (List<Map<?,?>>)value.get("rows");}
    @Test void validResultOnlyFormatsNoRepositoryWriteOrProjectContactQuery(){var d=data(input(row()));assertEquals(TENANT,d.get("tenant_id"));for(String key:List.of("can_import","writes_performed","notification_dispatched","preview_saved","job_created"))assertEquals(false,d.get(key));assertEquals("CURRENT_MEMBERSHIP_VERIFIED",d.get("tenant_authorization"));assertEquals("NOT_RUN",d.get("last_decision_maker_check"));assertEquals("NOT_RUN",d.get("existing_contact_check"));assertEquals(100,d.get("row_limit"));var facts=(Map<?,?>)rows(d).get(0).get("contact");assertEquals("EXPLICIT_INPUT",facts.get("source"));assertFalse(facts.containsKey("id"));assertFalse(facts.containsKey("version"));verify(platform).membership(ACTOR,TENANT);verifyNoMoreInteractions(platform);}
    @Test void eachRowHasStableIndexAndMalformedRowsDoNotDropValidFollowingRows(){var d=data(input(row(),NullNode.instance,mapper.createArrayNode(),row().put("enabled","true"),row()));assertEquals(2,d.get("valid_rows"));assertEquals(3,d.get("invalid_rows"));for(int i=0;i<5;i++)assertEquals(i+1,rows(d).get(i).get("row_number"));for(int i:List.of(1,2,3)){assertEquals("INVALID",rows(d).get(i).get("status"));assertNull(rows(d).get(i).get("contact"));}}
    @Test void missingUnknownAndForgedRowFieldsAreInvalidNeverScopeOverrides(){var missing=row();missing.remove("mobile");var d=data(input(missing,row().put("tenant_id",TENANT),row().put("id",ACTOR),row().put("contact_verification","VERIFIED"),row().put("expected_version",0)));assertEquals(5,d.get("invalid_rows"));assertEquals(0,d.get("valid_rows"));}
    @Test void duplicateRolePriorityAndNullEnabledNotCoerced(){var roles=row();roles.putArray("roles").add("REPORTER").add("REPORTER");var priorities=row();priorities.putArray("preferred_priorities").add("P1").add("P1");var d=data(input(roles,priorities,row().putNull("enabled")));assertEquals(3,d.get("invalid_rows"));}
    @Test void unknownVersusEmptyPreferencesAndExplicitQuietGroupRetained(){var a=row();var b=row();b.putArray("preferred_priorities");b.putObject("quiet_window").putNull("enabled").putNull("start").putNull("end");var d=data(input(a,b));assertEquals(2,d.get("valid_rows"));assertEquals(0,d.get("identical_rows"));var one=(Map<?,?>)rows(d).get(0).get("contact");var two=(Map<?,?>)rows(d).get(1).get("contact");assertNull(one.get("preferred_priorities"));assertEquals(List.of(),two.get("preferred_priorities"));assertNull(one.get("quiet_window"));assertNotNull(two.get("quiet_window"));}
    @Test void duplicateWarningKeepsEveryRowAndReferencesFirstExactValidRow(){var d=data(input(NullNode.instance,row(),row(),row().put("name","other"),row()));assertEquals(2,d.get("identical_rows"));assertEquals(2,rows(d).get(2).get("identical_to_row"));assertEquals(2,rows(d).get(4).get("identical_to_row"));assertEquals(5,rows(d).size());}
    @Test void maxRowsValidButWholeBodyEmptyOverLimitAndExtraRootFieldsRejected(){assertEquals(100,data(input(Collections.nCopies(100,row()).toArray(JsonNode[]::new))).get("valid_rows"));for(String body:List.of("{}","null","[]","{\"rows\":null}",input(),input(Collections.nCopies(101,row()).toArray(JsonNode[]::new)),"{\"rows\":[],\"tenant_id\":null}"))assertEquals(400,assertThrows(DomainException.class,()->data(body)).status);}
    @Test void strictJsonDuplicateKeysTrailingDepthAndBytesRejected(){for(String body:List.of("{\"rows\":[],\"rows\":[]}",input(row())+" {}",input(row()).replace("\"name\":\"synthetic\"","\"name\":\"x\",\"name\":\"y\""),"[[[[[[1]]]]]]"," ".repeat(CustomerContactImportPreviewController.MAX_BODY_BYTES+1)))assertEquals(400,assertThrows(DomainException.class,()->data(body)).status);}
    @Test void bothCurrentAdministratorRolesPermittedAndOthersDeniedBeforeBodyParsing(){for(String role:List.of("padmin","tadmin")){member(role,true,1);assertEquals(1,data(input(row())).get("valid_rows"));}for(String role:List.of("msp","viewer","unexpected")){member(role,true,1);assertEquals(403,assertThrows(DomainException.class,()->data("bad JSON")).status);}}
    @Test void currentMembershipExpirationVersionAndMissingIdentityFailClosed(){member("padmin",false,1);assertEquals(401,assertThrows(DomainException.class,()->data(input(row()))).status);member("padmin",true,0);assertEquals(401,assertThrows(DomainException.class,()->data(input(row()))).status);when(platform.membership(ACTOR,TENANT)).thenReturn(Optional.empty());assertEquals(401,assertThrows(DomainException.class,()->data(input(row()))).status);var r=request(input(row()));r.setUserPrincipal(null);assertEquals(401,assertThrows(DomainException.class,()->controller.preview(r)).status);}
    @Test void queriesAndMalformedSessionRejected(){var q=request(input(row()));q.addParameter("tenant_id",TENANT);assertEquals(400,assertThrows(DomainException.class,()->controller.preview(q)).status);var r=request(input(row()));r.getSession().setAttribute("mop.tenant_id",42);assertEquals(401,assertThrows(DomainException.class,()->controller.preview(r)).status);}
    @Test void validInternationalAddressAndCrossMidnightRemainUnverified(){var r=row().put("mobile","+8613800000000").put("email","a@example.test");r.putObject("quiet_window").put("enabled",true).put("start","22:00").put("end","07:00");var d=data(input(r));assertEquals(1,d.get("valid_rows"));var facts=(Map<?,?>)rows(d).get(0).get("contact");assertEquals("NOT_VERIFIED",facts.get("channel_verification"));assertNull(facts.get("delivery_eligible"));assertEquals("Asia/Shanghai",facts.get("quiet_timezone"));}
}
